cenozoApp.defineModule({name:"apex_analysis",models:["view"],create:module=>{angular.extend(module,{identifier:{parent:{subject:"exam",column:"exam.id"}},name:{singular:"analysis",plural:"analyses",possessive:"analysis'"}});module.addInputGroup("",{export_datetime:{title:"Export Date & Time",type:"datetime",isConstant:true},pass:{title:"Pass",type:"boolean"},note:{title:"Analysis Notes",type:"text"},apex_review_id:{type:"hidden"},uid:{column:"participant.uid",type:"hidden"}});cenozo.providers.directive("cnApexAnalysisImport",["CnApexAnalysisImportFactory","CnSession","$state",function(CnApexAnalysisImportFactory,CnSession,$state){return{templateUrl:module.getFileUrl("import.tpl.html"),restrict:"E",controller:async function($scope,$element){$scope.model=CnApexAnalysisImportFactory.instance();$scope.viewParent=async function(){await $state.go("apex_review.view",{identifier:$scope.model.parentModel.viewModel.record.apex_review_id})};await $scope.model.onView();CnSession.setBreadcrumbTrail([{title:"Apex Review"},{title:$scope.model.parentModel.viewModel.record.apex_review_id,go:async function(){$state.go("apex_review.view",{identifier:$scope.model.parentModel.viewModel.record.apex_review_id})}},{title:"Import"}])}}}]);cenozo.providers.directive("cnApexAnalysisExport",["CnApexAnalysisExportFactory","CnSession","$state",function(CnApexAnalysisExportFactory,CnSession,$state){return{templateUrl:module.getFileUrl("export.tpl.html"),restrict:"E",controller:async function($scope,$element){$scope.model=CnApexAnalysisExportFactory.instance();$scope.viewParent=async function(){await $state.go("apex_review.view",{identifier:$scope.model.parentModel.viewModel.record.apex_review_id})};await $scope.model.onView();CnSession.setBreadcrumbTrail([{title:"Apex Review"},{title:$scope.model.parentModel.viewModel.record.apex_review_id,go:async function(){$state.go("apex_review.view",{identifier:$scope.model.parentModel.viewModel.record.apex_review_id})}},{title:"Export"}]);$element.find("#selectedFileList")[0].size=$scope.model.fileList.length}}}]);cenozo.providers.factory("CnApexAnalysisImportFactory",["CnApexAnalysisModelFactory","CnHttpFactory","CnModalMessageFactory","CnModalConfirmFactory",function(CnApexAnalysisModelFactory,CnHttpFactory,CnModalMessageFactory,CnModalConfirmFactory){var object=function(){angular.extend(this,{parentModel:CnApexAnalysisModelFactory.instance(),isLoading:true,hostList:null,hostId:null,deletingFiles:false,downloadingFiles:false,deleteFiles:async function(){try{const hostName=this.hostList.findByProperty("value",this.hostId).name;const response=await CnModalConfirmFactory.instance({title:"Delete all Images on "+hostName,message:"Are you sure you wish to delete all images on "+hostName+"?"+"This operation cannot be reversed and any existing images and analysis will be lost."}).show();if(response){this.deletingFiles=true;await CnHttpFactory.instance({path:"apex_host/"+this.hostId,data:{delete:true}}).patch()}}finally{this.deletingFiles=false}},downloadFiles:async function(){},onView:async function(){this.isLoading=true;try{const hostResponse=await CnHttpFactory.instance({path:"apex_host",data:{select:{column:"name"},modifier:{order:"name"}}}).query();this.hostList=hostResponse.data.reduce((list,item)=>{list.push({value:item.id,name:item.name});return list},[]);this.hostId=0<this.hostList.length?this.hostList[0].value:null;await this.parentModel.viewModel.onView()}finally{this.isLoading=false}}})};return{instance:function(){return new object}}}]);cenozo.providers.factory("CnApexAnalysisExportFactory",["CnApexAnalysisModelFactory","CnHttpFactory","CnModalMessageFactory","CnModalConfirmFactory",function(CnApexAnalysisModelFactory,CnHttpFactory,CnModalMessageFactory,CnModalConfirmFactory){var object=function(){angular.extend(this,{parentModel:CnApexAnalysisModelFactory.instance(),isLoading:true,analysisFile:null,fileList:null,selectedFileList:[],hostList:null,hostId:null,checkingHostStatus:false,hostStatus:null,deletingFiles:false,uploadingFiles:false,checkHostStatus:async function(){angular.extend(this,{checkingHostStatus:true,hostStatus:null});try{const response=await CnHttpFactory.instance({path:"apex_host/"+this.hostId,data:{select:{column:"status"}}}).get();this.hostStatus=JSON.parse(response.data.status)}finally{this.checkingHostStatus=false}},deleteFiles:async function(){try{const hostName=this.hostList.findByProperty("value",this.hostId).name;const response=await CnModalConfirmFactory.instance({title:"Delete all Images on "+hostName,message:"Are you sure you wish to delete all images on "+hostName+"?"+"This operation cannot be reversed and any existing images and analysis will be lost."}).show();if(response){this.deletingFiles=true;await CnHttpFactory.instance({path:"apex_host/"+this.hostId,data:{delete:true}}).patch()}}finally{this.deletingFiles=false}},uploadFiles:async function(){if(null==this.analysisFile)return;this.uploadingFiles=true;try{let fileList=[this.analysisFile.filename].concat(this.selectedFileList);const response=await CnHttpFactory.instance({path:"apex_host/"+this.hostId,data:{files:fileList}}).patch();message=response.data.reduce((str,item)=>{let filename=item.file==this.analysisFile.filename?this.analysisFile.name:this.fileList.findByProperty("value",item.file).name;let result=null==item.error?"File successfully transferred.":item.error;let highlight=null==item.error?"text-success":"text-danger";let glyph=null==item.error?"glyphicon-ok":"glyphicon-remove";str+='<div class="container-fluid vertical-spacer">'+"<div>"+filename+"</div>"+'<div class="spacer '+highlight+'">'+result+' <i class="glyphicon '+glyph+'"></i>'+"</div>"+"</div>";return str},"");await CnModalMessageFactory.instance({title:"Upload Results",message:message,html:true,size:"lg"}).show();this.selectedFileList=[]}finally{this.uploadingFiles=false}},onView:async function(){this.isLoading=true;try{this.analysisFile=null;this.fileList=[];const hostResponse=await CnHttpFactory.instance({path:"apex_host",data:{select:{column:"name"},modifier:{order:"name"}}}).query();this.hostList=hostResponse.data.reduce((list,item)=>{list.push({value:item.id,name:item.name});return list},[]);this.hostId=0<this.hostList.length?this.hostList[0].value:null;await this.parentModel.viewModel.onView();const fileResponse=await CnHttpFactory.instance({path:"apex_analysis/"+this.parentModel.viewModel.record.id+"/image"}).query();this.analysisFile=null;this.fileList=fileResponse.data.reduce((list,item)=>{let name="Phase "+item.phase.rank+" ("+item.phase.name+"): "+(null==item.side?"":item.side+" ")+item.type;if(null!=item.number)name=name+" #"+item.number;if(item.reanalysed)name+=" (reanalysed)";if(item.analysis_image){this.analysisFile={name:name,filename:item.filename}}else{list.push({value:item.filename,name:name})}return list},[])}finally{this.isLoading=false}}})};return{instance:function(){return new object}}}])}});
